// Test shim: herdr's machine-aware primitives against two fake homes.
// exec runs a REAL shell with HOME pointed at the named machine's home,
// so $HOME-relative and absolute paths resolve exactly as on a machine.
import { spawnSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

// The rig root is two levels up from this vendored shim.
const RIG = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");

export const HOMES = {
  "": RIG + "/homeLocal",
  A: RIG + "/homeA",
  B: RIG + "/homeB",
};

const resolve = (p, on) => {
  let s = String(p);
  if (s.startsWith("$HOME/")) s = path.join(HOMES[on ?? ""], s.slice(6));
  else if (!s.startsWith("/")) s = path.join(HOMES[on ?? ""], s);
  return s;
};

export async function exec(cmd, args = [], opts = {}) {
  // Faithful to the app (src/mods.rs exec_future): null/absent on = this
  // machine; a named machine must exist; the empty string is NOT a machine
  // and rejects.
  if (opts.on === "") throw new Error('herd exec: unknown machine ""');
  if (opts.on != null && !(opts.on in HOMES)) throw new Error("herd exec: unknown machine " + opts.on);
  const r = spawnSync(cmd, args, {
    env: { ...process.env, HOME: HOMES[opts.on ?? ""] },
    encoding: "buffer", maxBuffer: 64 * 1024 * 1024,
  });
  return {
    code: r.status ?? 1,
    stdout: (r.stdout ?? Buffer.alloc(0)).toString("utf8"),
    stderr: (r.stderr ?? Buffer.alloc(0)).toString("utf8"),
  };
}

export async function readTextFile(p, opts = {}) {
  const abs = resolve(p, opts.on);
  if (!fs.existsSync(abs)) throw new Error("ENOENT: " + abs);
  return fs.readFileSync(abs, "utf8");
}
export const home = () => HOMES[""];
export const shared = () => undefined;
export const window = () => ({ platform: "linux" });
